template.script:
(function(){
  function init(){
    var modal = document.getElementById('certModal');
    if(!modal) return;
    var frame = document.getElementById('certFrame');
    var dl = document.getElementById('certDownload');
    function open(url){
      if(!url) return;
      frame.src = url;
      dl.href = url + (url.indexOf('?') >= 0 ? '&' : '?') + 'download=1';
      modal.classList.add('open');
    }
    function close(){ modal.classList.remove('open'); frame.src = 'about:blank'; }
    document.querySelectorAll('.js-cert-view').forEach(function(b){
      b.addEventListener('click', function(){ open(b.getAttribute('data-url')); });
    });
    var c = document.getElementById('certClose');
    if(c){ c.addEventListener('click', close); }
    modal.addEventListener('click', function(ev){ if(ev.target === modal){ close(); } });
    document.addEventListener('keydown', function(ev){ if(ev.key === 'Escape'){ close(); } });
  }
  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', init); } else { init(); }
})();

div.script:
(function () {
    var g = document.currentScript && document.currentScript.parentNode;
    if (!g || g.getAttribute('data-vista')) { return; }
    try {
        if (window.localStorage.getItem('shrimp_mkt_vista') === 'lista') { g.classList.add('s-products--list'); }
    } catch (e) {}
})();

t.script:
(function(){
  function init(){
    var btn = document.getElementById("loadMoreBtn");
    var wrap = document.getElementById("loadMoreWrap");
    var grid = document.getElementById("prodGrid");
    if(!btn || !wrap || !grid) return;
    var loading = false;
    btn.addEventListener("click", function(){
      if(loading) return;
      loading = true;
      var original = btn.innerHTML;
      btn.innerHTML = '<i class="fa fa-spinner fa-spin me-1"></i> Cargando…';
      btn.disabled = true;
      // Tarjetas "esqueleto" mientras llega la respuesta: el usuario ve
      // dónde aparecerán los productos en lugar de un salto brusco.
      var skels = [];
      for(var s = 0; s < 4; s++){
        var sk = document.createElement("div");
        sk.className = "s-skel-card";
        sk.setAttribute("aria-hidden", "true");
        sk.innerHTML = '<div class="s-skel-img"></div><div class="s-skel-body">'
          + '<div class="s-skel-line s-skel-line--short"></div><div class="s-skel-line"></div>'
          + '<div class="s-skel-line"></div><div class="s-skel-line s-skel-line--price"></div></div>';
        grid.appendChild(sk);
        skels.push(sk);
      }
      function quitarSkels(){ skels.forEach(function(sk){ sk.remove(); }); skels = []; }
      var params = new URLSearchParams();
      params.set("offset", wrap.getAttribute("data-next-offset") || "0");
      ["sort","q","stage","species","presentation","size_grade","location","seller","price_min","price_max","tipo","genetics","survival_min","pcr","spf"].forEach(function(k){
        var v = grid.getAttribute("data-" + k);
        if(v) params.set(k, v);
      });
      fetch("/marketplace/cards?" + params.toString(), {
        headers: {"X-Requested-With": "XMLHttpRequest"}
      }).then(function(r){ return r.json(); }).then(function(data){
        // Inserta las nuevas tarjetas SIN mover el scroll.
        quitarSkels();
        var tmp = document.createElement("div");
        tmp.innerHTML = data.html;
        // Cada tarjeta entra con un fundido y un leve ascenso, escalonado.
        var i = 0;
        while(tmp.firstChild){
          var nodo = tmp.firstChild;
          if(nodo.nodeType === 1){
            nodo.classList.add("s-card-in");
            nodo.style.animationDelay = Math.min(i, 11) * 55 + "ms";
            // Al terminar se quita: si no, la animación «congela» el
            // transform y la tarjeta pierde su efecto al pasar el ratón.
            nodo.addEventListener("animationend", function(){
              this.classList.remove("s-card-in");
              this.style.animationDelay = "";
            }, {once: true});
            i++;
          }
          grid.appendChild(nodo);
        }
        wrap.setAttribute("data-next-offset", data.next_offset);
        var shown = document.getElementById("shownCount");
        if(shown){ shown.textContent = data.shown_count; }
        if(data.has_more){
          btn.innerHTML = original;
          btn.disabled = false;
          loading = false;
        } else {
          btn.remove();
        }
      }).catch(function(){
        quitarSkels();
        btn.innerHTML = original;
        btn.disabled = false;
        loading = false;
      });
    });
  }
  if(document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded", init);
  } else { init(); }
})();

div.script:

(function () {

  function pad2(n){ return String(n).padStart(2,'0'); }
  function ymd(d){
    return d.getFullYear() + "-" + pad2(d.getMonth()+1) + "-" + pad2(d.getDate());
  }
  function monthTitle(d){
    const months = ["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"];
    return months[d.getMonth()] + " " + d.getFullYear();
  }

  async function loadEvents() {
    const payload = {
      jsonrpc: "2.0",
      method: "call",
      params: {},
      id: Date.now(),
    };

    const r = await fetch("/marketplace/calendar/events", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      credentials: "same-origin",
    });

    const data = await r.json();
    if (data.error) {
      throw new Error(data.error.data?.message || data.error.message || "Error RPC");
    }
    return data.result || [];
  }


  function showMsg(html, kind){
    const box = document.getElementById("calMsg");
    box.classList.remove("d-none");
    box.innerHTML =
      '<div class="alert alert-' + (kind || 'warning') + ' py-2 mb-0" style="border-radius:14px;">' +
      html + '</div>';
  }

  // ---- Seguridad: los datos de los eventos los escribe cualquier
  // vendedor (nombre del lote, ubicación, razón social). Antes se
  // concatenaban en innerHTML y un lote llamado
  // "<img src=x onerror=...>" ejecutaba JavaScript a todo visitante
  // del calendario público. Ahora todo valor entra como texto
  // (textContent) y la URL solo se acepta si es una ruta relativa
  // del propio sitio.
  function safeUrl(u){
    u = String(u || "");
    return (/^\/(?!\/)[^\s\\]*$/.test(u)) ? u : "#";
  }
  function el(tag, opts, children){
    const n = document.createElement(tag);
    opts = opts || {};
    if (opts.className) n.className = opts.className;
    if (opts.style) n.setAttribute("style", opts.style);
    if (opts.href !== undefined) n.setAttribute("href", safeUrl(opts.href));
    if (opts.text !== undefined) n.textContent = String(opts.text == null ? "" : opts.text);
    (children || []).forEach(function(c){ if (c) n.appendChild(c); });
    return n;
  }

  function buildIndex(events){
    const byDate = {};
    (events || []).forEach(e => {
      const d = (e.start || "").slice(0,10);
      if (!d) return;
      byDate[d] = byDate[d] || [];
      byDate[d].push(e);
    });
    return byDate;
  }

  function renderMonth(viewDate, byDate){
    const grid = document.getElementById("calGrid");
    const title = document.getElementById("calTitle");
    grid.innerHTML = "";
    title.textContent = monthTitle(viewDate);

    // calendario Lunes=0 ... Domingo=6
    const first = new Date(viewDate.getFullYear(), viewDate.getMonth(), 1);
    const last  = new Date(viewDate.getFullYear(), viewDate.getMonth()+1, 0);

    // convertir JS getDay (Dom=0) a (Lun=0)
    const firstDow = (first.getDay() + 6) % 7;
    const daysInMonth = last.getDate();

    const totalCells = Math.ceil((firstDow + daysInMonth)/7) * 7;

    const todayStr = ymd(new Date());

    for (let cell=0; cell<totalCells; cell++){
      const dayNum = cell - firstDow + 1;
      const inMonth = dayNum >= 1 && dayNum <= daysInMonth;

      const cellDate = new Date(viewDate.getFullYear(), viewDate.getMonth(), dayNum);
      const dateStr = inMonth ? ymd(cellDate) : "";

      const wrap = document.createElement("div");
      wrap.className = "p-2 s-cal-cell";
      wrap.style.minHeight = "110px";
      wrap.style.borderRight = "1px solid rgba(0,0,0,.06)";
      wrap.style.borderBottom = "1px solid rgba(0,0,0,.06)";
      wrap.style.background = inMonth ? "#fff" : "rgba(0,0,0,.015)";

      // marcador hoy
      if (inMonth && dateStr === todayStr){
        wrap.style.boxShadow = "inset 0 0 0 2px rgba(18,62,92,.25)";
        wrap.style.borderRadius = "10px";
      }

      if (!inMonth){
        grid.appendChild(wrap);
        continue;
      }

      const header = document.createElement("div");
      header.className = "d-flex justify-content-between align-items-center mb-1";
      header.appendChild(el("div", {style: "font-weight:900; font-size:13px;", text: dayNum}));

      const items = byDate[dateStr] || [];
      if (items.length){
        const badge = document.createElement("span");
        badge.className = "badge rounded-pill text-bg-light border";
        badge.style.fontWeight = "900";
        badge.textContent = items.length;
        header.appendChild(badge);
      }

      wrap.appendChild(header);

      // lista eventos (máx 3 + "ver más")
      const list = document.createElement("div");
      list.className = "d-grid gap-1 s-cal-events";
      list.style.gridTemplateColumns = "minmax(0, 1fr)";

      const maxShow = 3;
      items.slice(0, maxShow).forEach(ev => {
        const m = ev.meta || {};
        const a = el("a", {href: ev.url, className: "text-decoration-none", style: "display:block;"}, [
          el("div", {className: "px-2 py-1 rounded-3",
                     style: "border:1px solid rgba(18,62,92,.12); background:rgba(18,62,92,.06); font-size:12px;"}, [
            el("div", {style: "font-weight:900; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;",
                       text: m.name || ev.title || "Producto"}),
            el("div", {className: "text-muted",
                       style: "white-space:nowrap; overflow:hidden; text-overflow:ellipsis;",
                       text: (m.stage ? (m.stage + " • ") : "") + (m.seller || "")}),
          ]),
        ]);
        list.appendChild(a);
      });

      if (items.length > maxShow){
        const more = document.createElement("div");
        more.className = "text-muted";
        more.style.fontSize = "12px";
        more.textContent = "+" + (items.length - maxShow) + " más";
        list.appendChild(more);
      }

      wrap.appendChild(list);
      grid.appendChild(wrap);
    }
  }

  function renderList(byDate){
    const host = document.getElementById("calListView");
    host.innerHTML = "";
    const dates = Object.keys(byDate).sort();
    if(!dates.length){ return; }
    dates.forEach(function(d){
      const items = byDate[d];
      const sec = document.createElement("div");
      sec.className = "mb-3";
      const label = el("div", {className: "s-filter-sec-label", style: "margin-bottom:8px;"});
      const ico = document.createElement("i");
      ico.className = "fa fa-calendar";
      label.appendChild(ico);
      label.appendChild(document.createTextNode(" " + d + " · " + items.length + " producto(s)"));
      sec.appendChild(label);
      items.forEach(function(ev){
        const m = ev.meta || {};
        sec.appendChild(el("a", {href: ev.url, className: "mp-table-card",
            style: "display:flex; justify-content:space-between; gap:12px; align-items:center; padding:12px 16px; margin-bottom:8px; text-decoration:none;"}, [
          el("div", {style: "min-width:0;"}, [
            el("div", {style: "font-weight:800; color:var(--shrimp-ink);", text: m.name || ev.title || "Producto"}),
            el("div", {className: "text-faint", style: "font-size:13px;",
                       text: (m.stage ? (m.stage + " • ") : "") + (m.seller || "") + (m.location ? (" • " + m.location) : "")}),
          ]),
          el("div", {className: "text-end", style: "white-space:nowrap;"}, [
            el("div", {style: "font-weight:800;", text: (m.qty != null ? m.qty : "") + " " + (m.uom || "")}),
            el("div", {className: "text-faint", style: "font-size:13px;", text: m.price != null ? ("$" + m.price) : ""}),
          ]),
        ]));
      });
      host.appendChild(sec);
    });
  }

  function setupViewToggle(){
    const vc = document.getElementById("viewCal");
    const vl = document.getElementById("viewList");
    const calView = document.getElementById("calCalView");
    const listView = document.getElementById("calListView");
    const nav = document.getElementById("calNav");
    function setView(cal){
      calView.classList.toggle("d-none", !cal);
      listView.classList.toggle("d-none", cal);
      nav.style.display = cal ? "" : "none";
      vc.classList.toggle("s-btn-primary", cal); vc.classList.toggle("s-btn-ghost", !cal);
      vl.classList.toggle("s-btn-primary", !cal); vl.classList.toggle("s-btn-ghost", cal);
    }
    vc.addEventListener("click", function(){ setView(true); });
    vl.addEventListener("click", function(){ setView(false); });
  }

  document.addEventListener("DOMContentLoaded", async function () {
    let viewDate = new Date();
    viewDate = new Date(viewDate.getFullYear(), viewDate.getMonth(), 1);

    try {
      const events = await loadEvents();
      const byDate = buildIndex(events);

      if (!events || !events.length){
        showMsg("No hay productos publicados con <b>fecha tentativa de entrega</b> (expected_delivery_date).", "info");
      }

      renderMonth(viewDate, byDate);
      renderList(byDate);
      setupViewToggle();

      document.getElementById("calPrev").addEventListener("click", () => {
        viewDate = new Date(viewDate.getFullYear(), viewDate.getMonth()-1, 1);
        renderMonth(viewDate, byDate);
      });
      document.getElementById("calNext").addEventListener("click", () => {
        viewDate = new Date(viewDate.getFullYear(), viewDate.getMonth()+1, 1);
        renderMonth(viewDate, byDate);
      });
      document.getElementById("calToday").addEventListener("click", () => {
        const now = new Date();
        viewDate = new Date(now.getFullYear(), now.getMonth(), 1);
        renderMonth(viewDate, byDate);
      });

    } catch (e) {
      console.error(e);
      showMsg("No se pudieron cargar los eventos del calendario. Revisa el endpoint <code>/marketplace/calendar/events</code>.", "danger");
    }
  });

})();
